let inverterChoice; // Declare the inverter choice variable globally

  // Function to populate the inverter dropdown
  function populateInverterList() {
      const inverterSelector = document.querySelector("#InverterSelector");

      // Populate the inverter options dynamically
      for (let i = 1; i <= 42; i++) {
          let option = document.createElement("option");
          option.value = `INV${i}`;
          option.textContent = `INV${i}`;
          inverterSelector.appendChild(option);
      }
  }

  function updateReportPreview() {
      const datePicker = document.querySelector("#ReportDateTimePicker");
      const reportTypeSelector = document.querySelector("#ReportTypeSelector");
      const inverterSelector = document.querySelector("#InverterSelector");
      const iframe = document.querySelector("#ReportPreview");
      const inverterWrapper = document.querySelector("#InverterWrapper");
      const inverterLabel = document.querySelector("#InverterLabel");

      // Get selected values
      const selectedDate = datePicker.value;
      const reportType = reportTypeSelector.value;
      const selectedInverter = inverterSelector.value;

      // Ensure date is selected
      if (!selectedDate) {
          iframe.src = ""; // Clear preview if no date selected
          return;
      }

      const date = new Date(selectedDate);
      const year = date.getFullYear();
      const month = (date.getMonth() + 1).toString().padStart(2, '0');
      const day = date.getDate().toString().padStart(2, '0');

      let reportPath = "";

      // Show or hide Inverter selector based on report type
      if (reportType === "Daily" || reportType === "Monthly") {
          inverterWrapper.style.display = "block"; // Show inverter selection
      } else {
          inverterWrapper.style.display = "none"; // Hide inverter selection
      }

      // Build report path based on selected type
      if (reportType === "Daily" || reportType === "Monthly") {
          if (!selectedInverter) {
              iframe.src = ""; // Clear preview if no inverter selected
              return;
          }

          reportPath = reportType === "Daily"
              ? `http://localhost/Reports/Daily/${selectedInverter}_Daily_Report_${year}-${month}-${day}.pdf`
              : `http://localhost/Reports/Monthly/${selectedInverter}_Monthly_Report_${year}-${month}-${day}.pdf`;
      } else if (reportType === "DailyOverall") {
          reportPath = `http://localhost/Reports/DailyOverall/Daily_Report_${year}-${month}-${day}.pdf`;
      } else if (reportType === "MonthlyOverall") {
          reportPath = `http://localhost/Reports/MonthlyOverall/Monthly_Report_${year}-${month}-${day}.pdf`;
      }

      // Update iframe source to preview the report
      iframe.src = reportPath;

      // Log for debugging
      console.log("Report Path:", reportPath);
  }

  // Initialize Choices.js for the inverter dropdown
  document.addEventListener("DOMContentLoaded", () => {
      populateInverterList(); // Populate the inverter list dynamically

      inverterChoice = new Choices('#InverterSelector', {
          searchEnabled: true,
          placeholder: true,
          itemSelectText: '',
          shouldSort: false,
          removeItemButton: true,
      });

      // Trigger initial update for preview
      updateReportPreview();

      // Prevent page reload when changing date but maintain report selection
      const datePicker = document.querySelector("#ReportDateTimePicker");
      datePicker.addEventListener('change', updateReportPreview);
  });

let debounceTimer;

    function debounce(func, delay) {
        return function (...args) {
            clearTimeout(debounceTimer);
            debounceTimer = setTimeout(() => func.apply(this, args), delay);
        };
    }

    function populateInverterList() {
        const inverterSelector = document.querySelector("#InverterSelector");

        const deviceMapping = {
            'MV1': [1, 27],
            'MV2': [28, 38],
            'MV3': [39, 49],
            'LV4': [50, 52],
            'LV5': [53, 53],
            'LV6': [54, 57],
            'LV7': [58, 62]
        };

        for (const [loc, range] of Object.entries(deviceMapping)) {
            for (let i = range[0]; i <= range[1]; i++) {
                let deviceName = `${loc}_INV${i}`; 
                let option = document.createElement("option");
                option.value = deviceName;
                option.textContent = deviceName;
                inverterSelector.appendChild(option);
            }
        }
    }

    function updateReportPreview() {
        const datePicker = document.querySelector("#ReportDateTimePicker");
        const reportTypeSelector = document.querySelector("#ReportTypeSelector");
        const inverterSelector = document.querySelector("#InverterSelector");
        const iframe = document.querySelector("#ReportPreview");
        const inverterWrapper = document.querySelector("#InverterWrapper");

        const selectedDate = datePicker.value;
        const reportType = reportTypeSelector.value;
        const selectedInverter = inverterSelector.value;

        if (reportType === "DailyOverall" || reportType === "MonthlyOverall") {
            inverterSelector.disabled = true;
            inverterWrapper.style.opacity = "0.4"; 
        } else {
            inverterSelector.disabled = false;
            inverterWrapper.style.opacity = "1";
        }

        if (!selectedDate || !reportType) {
            iframe.src = ""; 
            return;
        }

        if ((reportType === "Daily" || reportType === "Monthly") && !selectedInverter) {
            iframe.src = ""; 
            return;
        }

        const date = new Date(selectedDate);
        const year = date.getFullYear();
        const month = (date.getMonth() + 1).toString().padStart(2, '0');
        const day = date.getDate().toString().padStart(2, '0');

        let reportPath = "";

        // Build report path based on selected type
        if (reportType === "Daily") {
            reportPath = `http://192.168.120.203/Reports/Daily/${selectedInverter}_Daily_Report_${year}-${month}-${day}.pdf`;
        } else if (reportType === "Monthly") {
            reportPath = `http://192.168.120.203/Reports/Monthly/${selectedInverter}_Monthly_Report_${year}-${month}-${day}.pdf`;
        } else if (reportType === "DailyOverall") {
            reportPath = `http://192.168.120.203/Reports/DailyOverall/Daily_Report_${year}-${month}-${day}.pdf`;
        } else if (reportType === "MonthlyOverall") {
            reportPath = `http://192.168.120.203/Reports/MonthlyOverall/Monthly_Report_${year}-${month}-${day}.pdf`;
        }

        iframe.src = reportPath;
    }

    // Initialize application events
    function initApp() {
        populateInverterList(); 

        document.querySelector("#ReportDateTimePicker").addEventListener("change", debounce(updateReportPreview, 100));
        document.querySelector("#ReportTypeSelector").addEventListener("change", debounce(updateReportPreview, 100));
        document.querySelector("#InverterSelector").addEventListener("change", debounce(updateReportPreview, 100));

        updateReportPreview();
    }

    if (document.readyState === 'loading') {
        document.addEventListener("DOMContentLoaded", initApp);
    } else {
        initApp();
    }

