function OnPageLoad() {

    var btn = document.getElementById("save_btn");
    var notification = document.getElementById("save_notification");

    if (!btn) return;

    btn.onclick = function () {

        const fields = [
            "size_dn", "class_meter", "resolution_meter",
            "q3", "ratio_r", "q1", "q2", "q4", "type_meter"
        ];

        let empty = false;

        // Reset highlight
        fields.forEach(id => {
            document.getElementById(id).style.border = "1px solid #ccc";
        });

        // Check empty
        fields.forEach(id => {
            const value = document.getElementById(id).value.trim();
            if (!value) {
                empty = true;
                document.getElementById(id).style.border = "2px solid red";
            }
        });

        if (empty) {
            notification.style.display = "none";
            return;
        }

        // Save values
        Envision.SetLocal("Size_DN", document.getElementById("size_dn").value);
        Envision.SetLocal("Class_Meter", document.getElementById("class_meter").value);
        Envision.SetLocal("Resolution", document.getElementById("resolution_meter").value);
        Envision.SetLocal("Q3", document.getElementById("q3").value);
        Envision.SetLocal("Ratio_R", document.getElementById("ratio_r").value);
        Envision.SetLocal("Q1", document.getElementById("q1").value);
        Envision.SetLocal("Q2", document.getElementById("q2").value);
        Envision.SetLocal("Q4", document.getElementById("q4").value);
        Envision.SetLocal("Type_Meter", document.getElementById("type_meter").value);

        // Show success notification
        notification.style.display = "block";
        setTimeout(() => notification.style.display = "none", 2500);
    };
}

